class Solution {
public:
    int minimumRecolors(string blocks, int k) {
        int n = blocks.size();
        int wCount = 0;
        for (int i = 0; i < k; i++) {
            if (blocks[i] == 'W') wCount++;
        }
        int minOps = wCount;
        for (int i = k; i < n; i++) {
            if (blocks[i - k] == 'W') wCount--;
            if (blocks[i] == 'W') wCount++;
            if (wCount < minOps) minOps = wCount;
        }
        return minOps;
    }
};
